-- 598: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 5 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_598_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_598_guard;
INSERT INTO _migration_598_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_017' AND NOT (q.topic_id IS 'topic_igcse_chem_stoichiometry' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many moles are there in 8 g of methane, CH₄? (Ar: C = 12, H = 1)' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 2 mol","B. 0.5 mol","C. 8 mol","D. 16 mol"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Mr of CH₄ = 12 + (4 × 1) = 16, so moles = mass ÷ Mr = 8 ÷ 16 = 0.5 mol. (2 mol inverts the division; 16 g, not 8 g, would be 1 mole.) Therefore the correct answer is B: 0.5 mol.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_017' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_598_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_018' AND NOT (q.topic_id IS 'topic_igcse_chem_stoichiometry' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many particles are there in one mole of any substance?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6.02 × 10²²","B. 1.60 × 10⁻¹⁹","C. 6.02 × 10²³","D. 12"]' AND q.correct_answer IS 'C' AND q.explanation IS 'One mole contains the Avogadro constant of particles: 6.02 × 10²³. (6.02 × 10²² is a tenth of a mole; 1.60 × 10⁻¹⁹ is the charge on an electron in coulombs; 12 g is the mass of one mole of carbon-12, not a particle count.) Therefore the correct answer is C: 6.02 × 10²³.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_018' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_598_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_019' AND NOT (q.topic_id IS 'topic_igcse_chem_stoichiometry' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When the equation CH₄ + O₂ → CO₂ + H₂O is correctly balanced, what is the coefficient of O₂?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1","B. 3","C. 4","D. 2"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Balancing gives CH₄ + 2O₂ → CO₂ + 2H₂O: one carbon and four hydrogens on each side, and 2 × 2 = 4 oxygens on the left matching 2 + 2 = 4 on the right. The coefficient of O₂ is therefore 2. Therefore the correct answer is D: 2.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_019' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_598_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_020' AND NOT (q.topic_id IS 'topic_igcse_chem_stoichiometry' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calcium carbonate decomposes on heating: CaCO₃ → CaO + CO₂. What mass of calcium oxide is formed when 50 g of calcium carbonate is completely decomposed? (Ar: Ca = 40, C = 12, O = 16)' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 28 g","B. 22 g","C. 56 g","D. 25 g"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Mr(CaCO₃) = 100, so 50 g is 50 ÷ 100 = 0.5 mol. The equation shows a 1 : 1 mole ratio, so 0.5 mol of CaO forms. Mr(CaO) = 40 + 16 = 56, giving a mass of 0.5 × 56 = 28 g. (22 g is the mass of the CO₂ released, 0.5 × 44; 56 g assumes 1 mol of CaO; 25 g simply halves the starting mass.) Therefore the correct answer is A: 28 g.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_020' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_017', 'topic_igcse_chem_stoichiometry', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'How many moles are there in 8 g of methane, CH₄? (Ar: C = 12, H = 1)', 'multiple_choice', NULL, '["A. 2 mol","B. 0.5 mol","C. 8 mol","D. 16 mol"]', 'B', 'Mr of CH₄ = 12 + (4 × 1) = 16, so moles = mass ÷ Mr = 8 ÷ 16 = 0.5 mol. (2 mol inverts the division; 16 g, not 8 g, would be 1 mole.) Therefore the correct answer is B: 0.5 mol.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_018', 'topic_igcse_chem_stoichiometry', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'How many particles are there in one mole of any substance?', 'multiple_choice', NULL, '["A. 6.02 × 10²²","B. 1.60 × 10⁻¹⁹","C. 6.02 × 10²³","D. 12"]', 'C', 'One mole contains the Avogadro constant of particles: 6.02 × 10²³. (6.02 × 10²² is a tenth of a mole; 1.60 × 10⁻¹⁹ is the charge on an electron in coulombs; 12 g is the mass of one mole of carbon-12, not a particle count.) Therefore the correct answer is C: 6.02 × 10²³.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_019', 'topic_igcse_chem_stoichiometry', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'When the equation CH₄ + O₂ → CO₂ + H₂O is correctly balanced, what is the coefficient of O₂?', 'multiple_choice', NULL, '["A. 1","B. 3","C. 4","D. 2"]', 'D', 'Balancing gives CH₄ + 2O₂ → CO₂ + 2H₂O: one carbon and four hydrogens on each side, and 2 × 2 = 4 oxygens on the left matching 2 + 2 = 4 on the right. The coefficient of O₂ is therefore 2. Therefore the correct answer is D: 2.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_020', 'topic_igcse_chem_stoichiometry', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Calcium carbonate decomposes on heating: CaCO₃ → CaO + CO₂. What mass of calcium oxide is formed when 50 g of calcium carbonate is completely decomposed? (Ar: Ca = 40, C = 12, O = 16)', 'multiple_choice', NULL, '["A. 28 g","B. 22 g","C. 56 g","D. 25 g"]', 'A', 'Mr(CaCO₃) = 100, so 50 g is 50 ÷ 100 = 0.5 mol. The equation shows a 1 : 1 mole ratio, so 0.5 mol of CaO forms. Mr(CaO) = 40 + 16 = 56, giving a mass of 0.5 × 56 = 28 g. (22 g is the mass of the CO₂ released, 0.5 × 44; 56 g assumes 1 mol of CaO; 25 g simply halves the starting mass.) Therefore the correct answer is A: 28 g.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge');
